const catalogs={'pt-BR':pt,'en-US':en,'es-ES':es};export function getLocale(){try{const v=localStorage.getItem('stackup.locale');return catalogs[v]?v:'pt-BR'}catch{return 'pt-BR'}}export function setLocale(locale){if(!catalogs[locale])throw new Error('Unsupported locale');try{localStorage.setItem('stackup.locale',locale)}catch{}document.documentElement.lang=locale;window.dispatchEvent(new CustomEvent('stackup:locale',{detail:locale}))}export function t(key,params={},locale=getLocale()){const value=catalogs[locale]?.[key]??catalogs['pt-BR'][key];if(value===undefined)throw new Error('Missing translation: '+key);return value.replace(/\{(\w+)\}/g,(_,k)=>String(params[k]??'{'+k+'}'))}
